node -e "
const XLSX = require('xlsx');

// Create workbook and worksheet
const wb = XLSX.utils.book_new();

const data = [
  ['Flight Number', 'Date', 'Time', 'Origin', 'Destination'],
  ['FL6BD665', '2026-09-05', '09:00', 'LAX', 'SFO']
];

const ws = XLSX.utils.aoa_to_sheet(data);

// Set column widths
ws['!cols'] = [
  { wch: 15 },  // Flight Number
  { wch: 12 },  // Date
  { wch: 8 },   // Time
  { wch: 8 },   // Origin
  { wch: 12 }   // Destination
];

XLSX.utils.book_append_sheet(wb, ws, 'Flights');
XLSX.writeFile(wb, 'skills/OfficeBench/testbed/data/travel_expenses.xlsx');

console.log('File created successfully!');

// Verify by reading it back
const wbRead = XLSX.readFile('skills/OfficeBench/testbed/data/travel_expenses.xlsx');
const sheet = wbRead.Sheets[wbRead.SheetNames[0]];
console.log(XLSX.utils.sheet_to_csv(sheet));
"
